// Validate and normalize incoming Lead Hunt payload
const raw = $input.first()?.json || {};
const body = raw.body || raw;

const niche = String(body.niche || '').trim();
const city = String(body.city || '').trim();

if (!niche || !city) {
  throw new Error('Validation failed: "niche" and "city" are required parameters.');
}

const requestedMax = Number(body.max_results || 20);
const maxResults = Math.max(1, Math.min(100, isNaN(requestedMax) ? 20 : requestedMax));

const noWebsite = Boolean(body.no_website);
const seoOpportunity = Boolean(body.seo_opportunity);
const socialOpportunity = Boolean(body.social_opportunity);

return [
  {
    json: {
      niche,
      city,
      max_results: maxResults,
      no_website: noWebsite,
      seo_opportunity: seoOpportunity,
      social_opportunity: socialOpportunity
    }
  }
];

const MONTHLY_LEAD_LIMIT = 125;
const MONTHLY_TOTAL_LIMIT = 250;

const now = new Date();
const currentYear = now.getUTCFullYear();
const currentMonth = now.getUTCMonth();

let leadSearches = 0;
let totalSearches = 0;

const rows = $input.all();

for (const item of rows) {
  const row = item.json;
  if (!row.created_at) continue;

  const createdAt = new Date(row.created_at);
  if (
    createdAt.getUTCFullYear() !== currentYear ||
    createdAt.getUTCMonth() !== currentMonth
  ) {
    continue;
  }

  totalSearches++;
  if (row.source === 'serpapi_maps' || row.source === 'serpapi_leads') {
    leadSearches++;
  }
}

const remainingLeadSearches = Math.max(0, MONTHLY_LEAD_LIMIT - leadSearches);
const remainingTotalSearches = Math.max(0, MONTHLY_TOTAL_LIMIT - totalSearches);

const config = $('Lead Input Normalization').first().json;

return [
  {
    json: {
      ...config,
      month: `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}`,
      lead_searches_used: leadSearches,
      lead_search_limit: MONTHLY_LEAD_LIMIT,
      lead_searches_remaining: remainingLeadSearches,
      total_searches_used: totalSearches,
      total_search_limit: MONTHLY_TOTAL_LIMIT,
      total_searches_remaining: remainingTotalSearches,
      lead_search_allowed: remainingLeadSearches > 0 && remainingTotalSearches > 0
    }
  }
];

const companies = $input.all().map(item => item.json);
const priorConfig = $('If Budget Allowed').first().json;

return [
  {
    json: {
      ...priorConfig,
      existing_companies: companies
    }
  }
];

const contacts = $input.all().map(item => item.json);
const priorState = $('Collapse Companies').first().json;

return [
  {
    json: {
      ...priorState,
      existing_contacts: contacts
    }
  }
];

const opportunities = $input.all().map(item => item.json);
const priorState = $('Collapse Contacts').first().json;

return [
  {
    json: {
      ...priorState,
      existing_opportunities: opportunities
    }
  }
];

const cfg = $input.first().json;

const niche = String(cfg.niche || '').trim();
const city = String(cfg.city || '').trim();

const query = `${niche} businesses`;

return [
  {
    json: {
      ...cfg,
      query,
      location: city,
      source: 'serpapi_maps',
      start: 0
    }
  }
];

const searchRun = $input.first().json;
const queryBuilder = $('LEAD QUERY BUILDER').first().json;

return [
  {
    json: {
      search_run_id: searchRun.id,
      query: queryBuilder.query,
      location: queryBuilder.location,
      start: 0
    }
  }
];

const resp = $input.first()?.json || {};
const serpSearch = $('PREPARE SERP SEARCH').first().json;
const searchRunId = serpSearch.search_run_id;

const results = Array.isArray(resp.local_results) ? resp.local_results : [];

if (results.length === 0) {
  return [
    {
      json: {
        has_results: false,
        search_run_id: searchRunId,
        raw_count: 0
      }
    }
  ];
}

// Deduplicate within this search execution by place_id or website or title+address
const seen = new Set();
const uniqueRaw = [];

results.forEach((business, index) => {
  const placeId = business.place_id || null;
  const dataId = business.data_id || null;
  const title = business.title || null;
  const address = business.address || '';

  // Clean actual business website (never use SerpApi internal endpoints or keys)
  let website = business.website || business.link || null;
  if (website && (website.includes('serpapi.com') || website.includes('api_key'))) {
    website = null;
  }

  // Build genuine Google Maps URL
  let googleMapsUrl = null;
  if (placeId) {
    googleMapsUrl = `https://www.google.com/maps/place/?q=place_id:${encodeURIComponent(placeId)}`;
  } else if (dataId) {
    googleMapsUrl = `https://www.google.com/maps/place/?q=place_id:${encodeURIComponent(dataId)}`;
  } else if (title) {
    const q = [title, address].filter(Boolean).join(' ');
    googleMapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
  }

  const dedupKey = placeId || website || `${title}|${address}`;
  if (seen.has(dedupKey)) {
    return;
  }
  seen.add(dedupKey);

  // Strip place_id_search from raw_data so SerpApi request URLs are never stored
  const sanitizedRawData = { ...business };
  delete sanitizedRawData.place_id_search;
  sanitizedRawData.google_maps_url = googleMapsUrl;

  uniqueRaw.push({
    json: {
      has_results: true,
      search_run_id: searchRunId,
      title,
      url: website,
      google_maps_url: googleMapsUrl,
      snippet: business.description || business.address || business.type || null,
      position: business.position || index + 1,
      raw_data: sanitizedRawData
    }
  });
});

return uniqueRaw;

// Intelligence, Evaluation, Qualification, and Deterministic Deduplication Engine
const rawSavedItems = $input.all();
const appContext = $('Collapse Opportunities').first().json;

const existingCompanies = appContext.existing_companies || [];
const existingContacts = appContext.existing_contacts || [];
const existingOpportunities = appContext.existing_opportunities || [];

const maxResults = appContext.max_results || 20;
const filterNoWebsite = Boolean(appContext.no_website);
const filterSeoOpp = Boolean(appContext.seo_opportunity);
const filterSocialOpp = Boolean(appContext.social_opportunity);

const searchRunId = $('PREPARE SERP SEARCH').first().json.search_run_id;

function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const GENERIC_DOMAINS = new Set([
  'sites.google.com',
  'google.com',
  'facebook.com',
  'instagram.com',
  'linkedin.com',
  'twitter.com',
  'x.com',
  'youtube.com',
  'whatsapp.com',
  'wa.me',
  'bit.ly',
  'linktr.ee'
]);

function normalizeDomain(url) {
  if (!url || typeof url !== 'string') return '';
  try {
    let u = url.trim();
    if (!u.startsWith('http://') && !u.startsWith('https://')) u = 'https://' + u;
    const parsed = new URL(u);
    let hostname = parsed.hostname.toLowerCase();
    if (hostname.startsWith('www.')) hostname = hostname.slice(4);
    return hostname;
  } catch (e) {
    return url.toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].trim();
  }
}

function normalizeName(name) {
  if (!name || typeof name !== 'string') return '';
  return name
    .toLowerCase()
    .replace(/\bpvt\b/g, '')
    .replace(/\bltd\b/g, '')
    .replace(/\bprivate\b/g, '')
    .replace(/\blimited\b/g, '')
    .replace(/\bllp\b/g, '')
    .replace(/\binc\b/g, '')
    .replace(/\bcorp\b/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
}

function normalizePhone(phone) {
  if (!phone || typeof phone !== 'string') return '';
  const digits = phone.replace(/\D/g, '');
  return digits.length >= 10 ? digits.slice(-10) : digits;
}

function getEntityKey(name, website) {
  const domain = normalizeDomain(website);
  const normName = normalizeName(name);
  if (domain && !GENERIC_DOMAINS.has(domain)) {
    return 'domain:' + domain;
  }
  return 'name:' + normName;
}

// Build index of existing companies
const companyLookup = new Map();
for (const c of existingCompanies) {
  const key = getEntityKey(c.name, c.website);
  if (!companyLookup.has(key)) {
    companyLookup.set(key, c);
  }
}

// Build index of existing contacts (company_id + normalized phone)
const contactLookup = new Set();
for (const c of existingContacts) {
  if (c.company_id && c.phone) {
    const p = normalizePhone(c.phone);
    if (p) contactLookup.add(`${c.company_id}|${p}`);
  }
}

// Build index of existing business_lead opportunities (company_id + type='business_lead')
const opportunityLookup = new Set();
for (const o of existingOpportunities) {
  if (o.company_id && (o.type === 'business_lead' || o.type === 'website_opportunity')) {
    opportunityLookup.add(o.company_id);
  }
}

const qualifiedLeads = [];
const seenInCurrentRun = new Set();

for (const item of rawSavedItems) {
  if (qualifiedLeads.length >= maxResults) break;

  const raw = item.json.raw_data || {};
  const name = String(raw.title || item.json.title || '').trim();
  if (!name) continue;

  let website = raw.website || item.json.url || null;
  if (website && (website.includes('serpapi.com') || website.includes('api_key') || website.includes('google.com/maps'))) {
    website = null;
  }
  const address = raw.address || null;
  const phone = raw.phone || null;
  const industry = raw.type || (Array.isArray(raw.types) ? raw.types[0] : null) || null;
  const location = address || null;
  let sourceUrl = raw.google_maps_url || item.json.google_maps_url || null;
  if (!sourceUrl || sourceUrl.includes('serpapi.com')) {
    const pId = raw.place_id || raw.data_id || null;
    if (pId) {
      sourceUrl = `https://www.google.com/maps/place/?q=place_id:${encodeURIComponent(pId)}`;
    } else if (name) {
      const q = [name, location].filter(Boolean).join(' ');
      sourceUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`;
    } else {
      sourceUrl = null;
    }
  }

  // 1. Deduplicate in current search execution
  const entityKey = getEntityKey(name, website);
  if (seenInCurrentRun.has(entityKey)) {
    continue;
  }
  seenInCurrentRun.add(entityKey);

  // 2. Website qualification
  const trimmedWeb = String(website || '').trim();
  let websiteStatus = 'not_found';
  let websiteOpp = false;
  if (trimmedWeb) {
    if (trimmedWeb.startsWith('http://') || trimmedWeb.startsWith('https://')) {
      websiteStatus = 'found';
    } else {
      websiteStatus = 'unknown';
    }
  }
  if (websiteStatus === 'not_found') {
    websiteOpp = true;
  }

  // 3. SEO qualification
  const rating = Number(raw.rating || 0);
  const reviews = Number(raw.reviews || 0);
  let seoOpp = false;
  const seoReasons = [];
  if (websiteStatus === 'not_found') {
    seoOpp = true;
    seoReasons.push('No website found');
  }
  if (websiteStatus === 'found') {
    seoReasons.push('Website found - SEO audit pending');
  }
  if (rating >= 4 && reviews >= 20) {
    seoReasons.push('Established Google Maps presence');
  }

  // 4. Social qualification
  const possibleLinks = [
    raw.facebook, raw.instagram, raw.linkedin, raw.youtube, raw.twitter, raw.x, raw.social_links
  ];
  const socialLinks = [];
  for (const v of possibleLinks) {
    if (Array.isArray(v)) socialLinks.push(...v.filter(Boolean));
    else if (v) socialLinks.push(v);
  }
  const uniqueSocial = [...new Set(socialLinks)];
  let socialStatus = uniqueSocial.length > 0 ? 'found' : 'not_found';
  let socialOpp = uniqueSocial.length === 0;
  let socialReason = socialOpp ? 'No social profile found in business data' : 'Social profile found';

  // 5. Lead scoring
  let score = 0;
  const reasons = [];
  if (websiteStatus === 'not_found') { score += 30; reasons.push('No website found'); }
  if (seoOpp) { score += 25; reasons.push('SEO opportunity detected'); }
  if (socialOpp) { score += 20; reasons.push('Social media opportunity detected'); }
  if (phone) { score += 10; reasons.push('Phone number available'); }
  if (rating >= 4.5) { score += 10; reasons.push(`Strong Google rating (${rating})`); }
  if (reviews >= 100) { score += 5; reasons.push(`Strong review volume (${reviews})`); }

  let priority = 'low';
  if (score >= 70) priority = 'high';
  else if (score >= 40) priority = 'medium';

  // 6. Respect incoming filters
  if (filterNoWebsite && websiteStatus !== 'not_found') {
    continue;
  }
  if (filterSeoOpp && !seoOpp) {
    continue;
  }
  if (filterSocialOpp && !socialOpp) {
    continue;
  }

  // 7. Check if company already exists
  let companyId;
  let isNewCompany = false;
  if (companyLookup.has(entityKey)) {
    const existing = companyLookup.get(entityKey);
    companyId = existing.id;
  } else {
    companyId = generateUUID();
    isNewCompany = true;
    companyLookup.set(entityKey, { id: companyId, name, website });
  }

  // 8. Check contact deduplication
  let isNewContact = false;
  let contactId = null;
  const normP = normalizePhone(phone);
  if (normP) {
    const contactKey = `${companyId}|${normP}`;
    if (!contactLookup.has(contactKey)) {
      isNewContact = true;
      contactId = generateUUID();
      contactLookup.add(contactKey);
    }
  }

  // 9. Check opportunity deduplication
  let isNewOpportunity = false;
  let opportunityId = null;
  if (!opportunityLookup.has(companyId)) {
    isNewOpportunity = true;
    opportunityId = generateUUID();
    opportunityLookup.add(companyId);
  }

  qualifiedLeads.push({
    json: {
      search_run_id: searchRunId,
      company_id: companyId,
      contact_id: contactId,
      opportunity_id: opportunityId,
      is_new_company: isNewCompany,
      is_new_contact: isNewContact,
      is_new_opportunity: isNewOpportunity,

      company_name: name,
      website,
      phone,
      address,
      location,
      industry,
      source_url: sourceUrl,
      raw_data: raw,

      website_status: websiteStatus,
      website_opportunity: websiteOpp,

      google_rating: rating || null,
      google_reviews: reviews || 0,
      seo_opportunity: seoOpp,
      seo_reason: seoReasons.join('; '),

      social_status: socialStatus,
      social_opportunity: socialOpp,
      social_links: uniqueSocial,
      social_reason: socialReason,

      lead_score: score,
      lead_priority: priority,
      score_reasons: reasons.join('; '),

      // Contact payload fields
      contact_name: null,
      contact_role: null,
      contact_email: null,
      contact_phone: phone,
      contact_whatsapp: null,
      contact_confidence: phone ? 0.8 : null,

      // Opportunity payload fields
      opp_title: `${priority.toUpperCase()} Lead Opportunity`,
      opp_type: 'business_lead',
      opp_match_score: score
    }
  });
}

return qualifiedLeads;

const items = $input.all();
const newCompanies = items.filter(i => i.json.is_new_company).map(i => i.json);

return [
  {
    json: {
      has_new_companies: newCompanies.length > 0,
      count: newCompanies.length,
      companies: newCompanies
    }
  }
];

const allLeads = $('DEDUPLICATE & EVALUATE LEADS').all();
const newContacts = allLeads.filter(i => i.json.is_new_contact).map(i => i.json);

return [
  {
    json: {
      has_new_contacts: newContacts.length > 0,
      count: newContacts.length,
      contacts: newContacts
    }
  }
];

const allLeads = $('DEDUPLICATE & EVALUATE LEADS').all();
const newOpps = allLeads.filter(i => i.json.is_new_opportunity).map(i => i.json);

return [
  {
    json: {
      has_new_opportunities: newOpps.length > 0,
      count: newOpps.length,
      opportunities: newOpps
    }
  }
];

const searchRunId = $('PREPARE SERP SEARCH').first().json.search_run_id;
const allLeads = $('DEDUPLICATE & EVALUATE LEADS').all();
const uniqueCount = allLeads.length;

return [
  {
    json: {
      search_run_id: searchRunId,
      status: 'completed',
      results_count: uniqueCount
    }
  }
];
